-- MAJ63 D : après 63c. Réexécutable. Réutilise le cron des notifications.
begin;
create table if not exists public.workshop_scheduled_announcements(id uuid primary key default gen_random_uuid(),message text not null,link_url text,link_label text,audience text not null,starts_at timestamptz not null,ends_at timestamptz,started_at timestamptz,finished_at timestamptz,created_by uuid references auth.users(id),version integer not null default 1);
alter table public.workshop_scheduled_announcements enable row level security;
revoke all on public.workshop_scheduled_announcements from public,anon,authenticated;
alter table public.workshop_announcement add column if not exists scheduled_id uuid references public.workshop_scheduled_announcements(id) on delete set null;
create or replace function public.workshop_announcement_schedule(p_id uuid,p_version integer,p_message text,p_link_url text,p_link_label text,p_audience text,p_start text,p_end text) returns void language plpgsql security definer set search_path='' as $$
declare a jsonb;s timestamptz;e timestamptz;r public.workshop_scheduled_announcements%rowtype;begin a:=workshop_private.actor();if not (a->>'manager')::boolean then raise exception 'Réservé aux gestionnaires.' using errcode='42501';end if;
s:=p_start::timestamp at time zone 'Europe/Paris';e:=nullif(p_end,'')::timestamp at time zone 'Europe/Paris';
if s is null or s<=now() or (e is not null and e<=s) or p_message is null or length(trim(p_message)) not between 1 and 1000 or p_audience is null or p_audience not in ('all','early_lunch','late_lunch','encadrants') then raise exception 'Message, destinataires et dates futures valides requis.';end if;
if nullif(trim(p_link_url),'') is not null and (not workshop_private.valid_link(p_link_url) or length(trim(coalesce(p_link_label,''))) not between 1 and 80) then raise exception 'Lien ou libellé invalide.';end if;
perform pg_advisory_xact_lock(hashtextextended('announcement-schedule63',0));select * into r from public.workshop_scheduled_announcements where id=p_id for update;
if p_id is not null and (r.id is null or r.version is distinct from p_version or r.started_at is not null or r.finished_at is not null) then raise exception 'Programmation modifiée ou déjà commencée.';end if;
if exists(select 1 from public.workshop_scheduled_announcements x where x.id is distinct from p_id and x.finished_at is null and tstzrange(x.starts_at,x.ends_at,'[)') && tstzrange(s,e,'[)')) then raise exception 'Une autre annonce occupe déjà cette période. Ajuste les dates.';end if;
if p_id is null then insert into public.workshop_scheduled_announcements(message,link_url,link_label,audience,starts_at,ends_at,created_by) values(trim(p_message),nullif(trim(p_link_url),''),nullif(trim(p_link_label),''),p_audience,s,e,auth.uid());else update public.workshop_scheduled_announcements set message=trim(p_message),link_url=nullif(trim(p_link_url),''),link_label=nullif(trim(p_link_label),''),audience=p_audience,starts_at=s,ends_at=e,version=version+1 where id=p_id;end if;end $$;
create or replace function public.workshop_announcement_schedules() returns jsonb language plpgsql security definer set search_path='' as $$declare a jsonb;begin a:=workshop_private.actor();if not (a->>'manager')::boolean then raise exception 'Réservé aux gestionnaires.' using errcode='42501';end if;return(select coalesce(jsonb_agg(to_jsonb(s)-'created_by' order by starts_at),'[]') from public.workshop_scheduled_announcements s where finished_at is null);end $$;
create or replace function public.workshop_announcement_cancel(p_id uuid,p_version integer) returns void language plpgsql security definer set search_path='' as $$declare a jsonb;begin a:=workshop_private.actor();if not (a->>'manager')::boolean then raise exception 'Réservé aux gestionnaires.' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('announcement-schedule63',0));update public.workshop_scheduled_announcements set finished_at=now(),version=version+1 where id=p_id and version=p_version and finished_at is null;if not found then raise exception 'Programmation modifiée ailleurs.';end if;update public.workshop_announcement set enabled=false,scheduled_id=null,updated_at=now() where scheduled_id=p_id;end $$;
create or replace function workshop_private.publish_scheduled(p_now timestamptz) returns void language plpgsql security definer set search_path='' as $$declare r record;begin
perform pg_advisory_xact_lock(hashtextextended('announcement-schedule63',0));
for r in select * from public.workshop_scheduled_announcements where finished_at is null and ends_at<=p_now for update loop update public.workshop_announcement set enabled=false,scheduled_id=null,updated_at=p_now where scheduled_id=r.id;update public.workshop_scheduled_announcements set finished_at=p_now,version=version+1 where id=r.id;end loop;
for r in select * from public.workshop_scheduled_announcements where started_at is null and finished_at is null and starts_at<=p_now and (ends_at is null or ends_at>p_now) order by starts_at for update loop
update public.workshop_announcement set message=r.message,link_url=r.link_url,link_label=r.link_label,audience=r.audience,enabled=true,updated_at=p_now,scheduled_id=r.id where id=1;
update public.workshop_scheduled_announcements set started_at=p_now,version=version+1 where id=r.id;end loop;end $$;
do $$begin
if to_regprocedure('workshop_private.schedule_messages_before63(timestamptz)') is null then alter function workshop_private.schedule_messages(timestamptz) rename to schedule_messages_before63;end if;
if to_regprocedure('public.workshop_load_before63(date)') is null then alter function public.workshop_load(date) rename to workshop_load_before63;end if;
if to_regprocedure('public.workshop_save_announcement_before63(text,boolean,text,text,text)') is null then alter function public.workshop_save_announcement_v52(text,boolean,text,text,text) rename to workshop_save_announcement_before63;end if;end $$;
create or replace function workshop_private.schedule_messages(p_now timestamptz) returns void language plpgsql security definer set search_path='' as $$begin perform workshop_private.publish_scheduled(p_now);perform workshop_private.schedule_messages_before63(p_now);end $$;
create or replace function public.workshop_load(p_date date) returns jsonb language plpgsql security definer set search_path='' as $$begin perform workshop_private.actor_before30();perform workshop_private.publish_scheduled(now());return public.workshop_load_before63(p_date);end $$;
create or replace function public.workshop_save_announcement_v52(p_message text,p_enabled boolean,p_link_url text,p_link_label text,p_audience text) returns void language plpgsql security definer set search_path='' as $$begin perform public.workshop_save_announcement_before63(p_message,p_enabled,p_link_url,p_link_label,p_audience);update public.workshop_announcement set scheduled_id=null where id=1;end $$;
revoke all on function workshop_private.publish_scheduled(timestamptz),workshop_private.schedule_messages_before63(timestamptz),workshop_private.schedule_messages(timestamptz),public.workshop_load_before63(date),public.workshop_save_announcement_before63(text,boolean,text,text,text),public.workshop_announcement_schedule(uuid,integer,text,text,text,text,text,text),public.workshop_announcement_schedules(),public.workshop_announcement_cancel(uuid,integer),public.workshop_load(date),public.workshop_save_announcement_v52(text,boolean,text,text,text) from public,anon,authenticated;
grant execute on function public.workshop_announcement_schedule(uuid,integer,text,text,text,text,text,text),public.workshop_announcement_schedules(),public.workshop_announcement_cancel(uuid,integer),public.workshop_load(date),public.workshop_save_announcement_v52(text,boolean,text,text,text) to authenticated;
notify pgrst,'reload schema';commit;
